import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';

/// Troc's launcher icon is generated by `tools/troc_launcher_icon.py`, not by `flutter_launcher_icons`.
/// Pin what Android needs from it, so that a partial regeneration, or a run of `flutter_launcher_icons`
/// that rewrites the adaptive icon, fails here. Whether the files are exactly what the script draws is
/// checked with `python3 tools/troc_launcher_icon.py --check`, which needs Pillow.
void main() {
  const densities = {
    'mdpi': 1.0,
    'hdpi': 1.5,
    'xhdpi': 2.0,
    'xxhdpi': 3.0,
    'xxxhdpi': 4.0,
  };

  test(
    'the adaptive icon has a background, a foreground and a monochrome layer',
    () {
      final xml = File(
        'android/app/src/main/res/mipmap-anydpi-v26/launcher_icon.xml',
      ).readAsStringSync();
      for (final layer in ['background', 'foreground', 'monochrome']) {
        expect(
          xml,
          contains('<$layer android:drawable="@drawable/ic_launcher_$layer"/>'),
        );
      }
    },
  );

  test('every density has its layers and its legacy icon, at the right size', () {
    for (final variant in ['main', 'debug']) {
      final res = 'android/app/src/$variant/res';
      for (final MapEntry(key: density, value: scale) in densities.entries) {
        // Layer name: whether it needs transparency. Debug has its own foreground and background,
        // and falls back to main for the monochrome layer.
        final layers = {
          'foreground': true,
          'background': false,
          if (variant == 'main') 'monochrome': true,
        };
        for (final MapEntry(key: layer, value: needsAlpha) in layers.entries) {
          final path = '$res/drawable-$density/ic_launcher_$layer.png';
          final png = _readPngHeader(path);
          expect(png.size, (108 * scale).round(), reason: path);
          if (needsAlpha) {
            expect(png.hasAlpha, isTrue, reason: path);
          }
        }
        final legacy = ['launcher_icon', if (variant == 'main') 'ic_launcher'];
        for (final name in legacy) {
          final path = '$res/mipmap-$density/$name.png';
          expect(_readPngHeader(path).size, (48 * scale).round(), reason: path);
        }
      }
    }
  });
}

/// Side of a square PNG and whether it has an alpha channel, read from its IHDR chunk.
({int size, bool hasAlpha}) _readPngHeader(String path) {
  final bytes = File(path).readAsBytesSync();
  const signature = [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];
  expect(bytes.sublist(0, 8), signature, reason: '$path is not a PNG');
  final header = ByteData.sublistView(bytes, 16, 26);
  final width = header.getUint32(0);
  expect(header.getUint32(4), width, reason: '$path is not square');
  // Colour type 4 is grey with alpha, 6 is RGB with alpha.
  final colourType = header.getUint8(9);
  return (size: width, hasAlpha: colourType == 4 || colourType == 6);
}
